uniform vec2 uTexSize;
#define texsize vec4(uTexSize, 1.0/uTexSize)

// Random values
uniform vec2 uRandomPreset;
uniform vec2 uRandomFrame;
uniform vec4 rand_preset;
uniform vec4 rand_frame;

// Input from vertex shader
in vec2 vUv;
in vec2 vUvOriginal;
in float vRadius;
in float vAngle;

// Output
