vec3 dy = ( GetBlur1(uv_z+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv_z-vec2( 0.0 , 1.0 )*d).xy );
vec3 c1 = mix( 0.0 ,vec3( 0.0 ,0.5,0.8),texture(sampler_fc_main,uv6).y);
